// Voice command routing (added feature, v40).
//
// The main process streams recognized words to the renderer. Two different
// pairs produce `command: "movement"`:
//
//   scheme pair   - 开启 / 关闭 (or 开始 / 停止, 打开 / 关闭): switches the
//                   whole tracking session, i.e. exactly what the mouse-mode
//                   hotkey does. Tracking off also means no clicking.
//   feature pair  - 移动 / 静止: only the CURSOR MOVEMENT is switched. The
//                   cursor parks where it is, but the camera keeps running, so
//                   a mouth or blink click still fires (each of those has its
//                   own clutch). Before v40 "静止" took the scheme path and
//                   stopped clicking as well, which is not what the word means.
//
// This module turns a payload plus the current UI state into a single
// intention, so the routing is unit-testable without a camera, a DOM or IPC.
// The renderer only performs the side effects (start/stop, toast, checkbox).

/**
 * @param {{action?: string, command?: string, source?: string}} payload
 * @param {{paused: boolean, cursorMovementOff: boolean}} state
 * @returns {{type: string, key?: string, value?: boolean}}
 *   type ∈ "start" | "stop" | "already-on" | "already-off"
 *        | "movement-off" | "movement-off-already" | "movement-on"
 *        | "movement-on-already" | "start-and-movement-on"
 *        | "checkbox" | "ignore"
 */
export function decideVoiceCommand(payload, { paused, cursorMovementOff }) {
	const action = payload?.action === "off" ? "off" : "on";
	const command = payload?.command || "movement";
	// Older main processes don't send `source`; treat that as the scheme pair,
	// which is the v36-and-earlier behavior.
	const source = payload?.source || "scheme";

	if (command === "movement" && source === "movement") {
		if (action === "off") {
			return { type: cursorMovementOff ? "movement-off-already" : "movement-off" };
		}
		if (paused) {
			// Movement can't come back without the camera: start tracking, which
			// also clears cursorMovementOff (updatePaused does that).
			return { type: "start-and-movement-on" };
		}
		return { type: cursorMovementOff ? "movement-on" : "movement-on-already" };
	}

	if (command === "movement") {
		if (action === "on") {
			return { type: paused ? "start" : "already-on" };
		}
		return { type: paused ? "already-off" : "stop" };
	}

	if (command === "blink" || command === "mouth") {
		return { type: "checkbox", key: command, value: action === "on" };
	}

	return { type: "ignore" };
}
